            det += (-1) ** j * A[0][j] * determinant(submatrix)
        return det

    def polynomial_ring_order(n):
        # Define the polynomial ring over F_2
        variables = list(range(1, n + 1))
        monomials = [tuple(sorted(random.sample(variables, k))) for k in range(1, n + 1)]

